analyze.mjs.text:
// Classifies one hostname's CNAME chain plus (optionally) a live HTTP probe
// of that hostname into a subdomain-takeover verdict. Pure function, no I/O,
// no network -- imported identically by the CLI (check.mjs) and the browser
// page (index.html), the same split every checker in this portfolio uses.
//
// What each category means:
//
//   no-cname             The hostname has no CNAME record (resolves via A/
//                         AAAA directly, or does not resolve at all). This
//                         check only applies to CNAME-based hosting; nothing
//                         to report either way.
//   not-risky            The CNAME target does not match any provider in
//                         `fingerprints.mjs`. Not evidence of safety -- see
//                         `no-known-provider` below -- but also not risky by
//                         this tool's own knowledge.
//   dangling-confirmed   The CNAME target matches a known takeover-prone
//                         provider AND a live GET to the hostname returned
//                         that exact provider's own "nothing is claimed at
//                         this name" fingerprint text. The strongest signal
//                         this tool can produce -- real, live evidence, not
//                         an inference from DNS alone.
//   risky-unconfirmed    The CNAME target matches a known provider, but the
//                         HTTP probe did not confirm the fingerprint (either
//                         because the probe couldn't complete -- commonly a
//                         browser CORS block -- or because the response
//                         didn't match, which usually means the target is
//                         actually claimed and this is a false alarm at the
//                         DNS layer alone). Worth a manual look, never
//                         treated as confirmed.
//   lookup-error          The DNS lookup itself failed (resolver timeout,
//                         network error). Never read as either finding.
//
// `severity` on a finding is set once, here, and never escalated by a
// caller: `dangling-confirmed` is `critical`, `risky-unconfirmed` is
// `warning`. A provider's `vulnerable: false` (see fingerprints.mjs) does
// not downgrade a `dangling-confirmed` verdict -- a live fingerprint match is
// live evidence regardless of this tool's own belief about the provider's
// current mitigations, and `vulnerable` is surfaced in the finding only as
// context for a human reader to weigh.

import { matchProvider } from './fingerprints.mjs';

/**
 * @param {string} hostname - the hostname checked, for display only
 * @param {object} cname - lookup.mjs's `resolveCnameChain` result:
 *   { chain: string[], finalTarget: string|null, truncated: boolean, error: string|null }
 * @param {object|null} probe - probe.mjs's `fetchHost` result, or null when
 *   no CNAME target matched a known provider (no probe was worth sending)
 */
export function classify(hostname, cname, probe) {
  if (cname.error) {
    return {
      hostname,
      category: 'lookup-error',
      chain: cname.chain,
      provider: null,
      probe: null,
      error: cname.error,
    };
  }

  if (!cname.finalTarget) {
    return {
      hostname,
      category: 'no-cname',
      chain: cname.chain,
      provider: null,
      probe: null,
      error: null,
    };
  }

  const provider = matchProvider(cname.finalTarget);
  if (!provider) {
    return {
      hostname,
      category: 'not-risky',
      chain: cname.chain,
      provider: null,
      probe: null,
      error: null,
    };
  }

  if (!probe || !probe.ok) {
    return {
      hostname,
      category: 'risky-unconfirmed',
      chain: cname.chain,
      provider,
      probe: probe ?? null,
      error: probe?.error ?? null,
    };
  }

  const confirmed = provider.fingerprint.test(probe.text ?? '');
  return {
    hostname,
    category: confirmed ? 'dangling-confirmed' : 'risky-unconfirmed',
    chain: cname.chain,
    provider,
    probe,
    error: null,
  };
}

function findingFor(result) {
  if (result.category === 'dangling-confirmed') {
    return {
      id: `takeover-confirmed-${result.hostname}`,
      severity: 'critical',
      hostname: result.hostname,
      provider: result.provider.name,
      target: result.chain[result.chain.length - 1],
      title: `${result.hostname} is a confirmed dangling CNAME to ${result.provider.name}`,
      detail:
        `The CNAME chain ends at ${result.chain[result.chain.length - 1]}, which matches ${result.provider.name}'s ` +
        `own hostname pattern, and a live GET to https://${result.hostname}/ returned that provider's own ` +
        `"nothing is claimed at this name" page. Unless this is intentional (a domain being decommissioned on ` +
        `purpose), remove the DNS record now, or reclaim the name on ${result.provider.name} before anyone else can.`,
      docsUrl: result.provider.docsUrl,
    };
  }
  if (result.category === 'risky-unconfirmed') {
    return {
      id: `takeover-unconfirmed-${result.hostname}`,
      severity: 'warning',
      hostname: result.hostname,
      provider: result.provider.name,
      target: result.chain[result.chain.length - 1],
      title: `${result.hostname} points at ${result.provider.name}, a known takeover-prone provider`,
      detail: result.probe && result.probe.ok
        ? `The CNAME target matches ${result.provider.name}, but the live response did not match that provider's ` +
          `known "unclaimed" page -- this usually means the target is actually claimed and in use. Worth a manual ` +
          `look if you don't recognise it.`
        : `The CNAME target matches ${result.provider.name}, but this run could not confirm it live${
          result.error ? ` (${result.error})` : ''
        } -- commonly a browser CORS block. Re-run with the CLI, or check the target manually.`,
      docsUrl: result.provider.docsUrl,
    };
  }
  return null;
}

/**
 * @param {string[]} hostnames
 * @param {object[]} results - one `classify()` result per hostname
 */
export function buildReport(hostnames, results) {
  const list = Array.isArray(results) ? results : [];
  const findings = list.map(findingFor).filter(Boolean);
  const confirmedCount = findings.filter((f) => f.severity === 'critical').length;
  const unconfirmedCount = findings.filter((f) => f.severity === 'warning').length;
  const errors = list.filter((r) => r.category === 'lookup-error');

  return {
    hostnamesChecked: list.length,
    results: list,
    findings,
    confirmedCount,
    unconfirmedCount,
    errors,
    incomplete: errors.length > 0,
    ok: confirmedCount === 0 && unconfirmedCount === 0,
  };
}

check.mjs.text:
#!/usr/bin/env node
// CLI: for each hostname given, follows its CNAME chain (real DNS, over
// Cloudflare's public DNS-over-HTTPS resolver), and when the chain ends at a
// known takeover-prone provider, sends one live GET request to the hostname
// to check whether that provider's own "nothing is claimed at this name"
// page comes back. Your machine, real requests -- no request goes through
// this portfolio.
//
//   node check.mjs <hostname> [<hostname> ...] [--json] [--timeout <ms>]
//
// Only run this against a hostname you own or are authorised to test -- the
// DNS lookup and the single GET are the same requests any browser visiting
// the hostname already makes. This never attempts to claim, register, or
// configure anything at a provider -- it only detects and reports.
//
// Exit code 0 when no hostname is confirmed or unconfirmed-risky; 1 when at
// least one is, or a lookup could not be completed at all.

import { resolveCnameChain } from './lookup.mjs';
import { fetchHostname } from './probe.mjs';
import { classify, buildReport } from './analyze.mjs';
import { matchProvider } from './fingerprints.mjs';

function formatText(report) {
  const lines = [];
  lines.push(`Hostnames checked: ${report.hostnamesChecked}`);
  lines.push('');

  if (report.findings.length === 0) {
    lines.push('No subdomain-takeover risk found among the hostnames checked.');
  } else {
    for (const f of report.findings) {
      lines.push(`!! [${f.severity.toUpperCase()}] ${f.title}`);
      lines.push(`     ${f.detail}`);
      lines.push(`     target: ${f.target}`);
      lines.push(`     docs: ${f.docsUrl}`);
      lines.push('');
    }
  }

  const clean = report.results.filter((r) => r.category === 'no-cname' || r.category === 'not-risky');
  if (clean.length > 0) {
    lines.push(`${clean.length} hostname(s) with no risky CNAME target found.`);
  }
  if (report.errors.length > 0) {
    lines.push(`${report.errors.length} hostname(s) could not be looked up: ${report.errors.map((e) => `${e.hostname} (${e.error})`).join('; ')}`);
  }

  lines.push('');
  lines.push(
    'This is evidence from a DNS lookup and one GET request per hostname, not a full security ' +
      'audit -- see README.md for what this tool does and does not check.',
  );
  return lines.join('\n');
}

function parseArgs(argv) {
  const hostnames = [];
  let json = false;
  let timeoutMs;
  for (let i = 0; i < argv.length; i++) {
    if (argv[i] === '--json') json = true;
    else if (argv[i] === '--timeout') timeoutMs = Number(argv[++i]);
    else if (!argv[i].startsWith('--')) hostnames.push(argv[i]);
  }
  return { hostnames, json, timeoutMs };
}

/** Pure orchestration: given injectable lookup/probe functions, resolve and
 * classify every hostname. Kept separate from main() so tests can inject
 * fakes instead of hitting the network. Only sends a probe request when the
 * CNAME chain actually ends at a known provider -- no point sending a live
 * request that classify() cannot use either way. */
export async function runCheck(hostnames, { resolveCnameChainFn = resolveCnameChain, fetchHostnameFn = fetchHostname, timeoutMs } = {}) {
  const results = await Promise.all(
    hostnames.map(async (hostname) => {
      const cname = await resolveCnameChainFn(hostname, timeoutMs ? { timeoutMs } : undefined);
      if (cname.error || !cname.finalTarget || !matchProvider(cname.finalTarget)) {
        return classify(hostname, cname, null);
      }
      const probe = await fetchHostnameFn(hostname, timeoutMs ? { timeoutMs } : undefined);
      return classify(hostname, cname, probe);
    }),
  );
  return buildReport(hostnames, results);
}

async function main() {
  const args = parseArgs(process.argv.slice(2));
  if (args.hostnames.length === 0) {
    console.error('Usage: node check.mjs <hostname> [<hostname> ...] [--json] [--timeout <ms>]');
    console.error('Only run this against a hostname you own or are authorised to test.');
    process.exit(2);
  }

  const report = await runCheck(args.hostnames, { timeoutMs: args.timeoutMs });

  if (args.json) {
    console.log(JSON.stringify(report, null, 2));
  } else {
    console.log(formatText(report));
  }
  process.exit(report.ok ? 0 : 1);
}

if (import.meta.url === `file://${process.argv[1]}`) {
  main();
}

fingerprints.mjs.text:
// The provider fingerprint table this whole venture is built on: for each
// third-party host a CNAME can point at, a pattern that recognises the CNAME
// target and a body fingerprint that recognises that provider's own "nothing
// is claimed at this name" response page.
//
// A subdomain takeover happens when (1) a DNS CNAME still points at a
// third-party service, but (2) whatever used to be configured there (an S3
// bucket, a Heroku app, a GitHub Pages site) has been deleted or was never
// created, so (3) the service's own edge answers with a generic "not found"
// page instead of 404-ing the DNS name itself -- and (4) most of these
// services let *anyone* claim that unclaimed name on their platform, which
// then makes the victim's own subdomain serve the attacker's content, under
// the victim's own domain, including its cookies and any CSP/CORS trust that
// domain carries.
//
// This list is deliberately curated rather than exhaustive -- see
// README.md's "Coverage, deliberately partial" section. Every fingerprint
// below is public information: the same "which page comes back when nothing
// is configured" signatures documented across years of public security
// research and the open-source subdomain-takeover scanners that predate this
// tool (documented independently here, not reproduced from any one source).
// A miss (a real dangling record whose provider or wording isn't in this
// table) is reported as `no-known-provider`, never as a false "safe" --
// see analyze.mjs.
//
// `vulnerable` records this portfolio's own best current read of whether the
// provider still allows an unauthenticated visitor to claim an arbitrary
// unclaimed name (`true`), has shipped domain-verification or a similar
// mitigation since the class became well known (`false` -- worth knowing
// about but a materially lower real risk), or is genuinely unclear from
// public documentation alone (`null`). This can go stale as providers ship
// or roll back mitigations -- `note` says why the read is what it is, and
// `analyze.mjs` never escalates severity on the strength of `vulnerable`
// alone; see its own header.

export const PROVIDERS = [
  {
    id: 'aws-s3',
    name: 'Amazon S3 (static website hosting)',
    cnamePattern: /(^|\.)s3(-website[.-][a-z0-9-]+)?\.amazonaws\.com$/i,
    fingerprint: /NoSuchBucket|The specified bucket does not exist/i,
    vulnerable: true,
    docsUrl: 'https://docs.aws.amazon.com/AmazonS3/latest/userguide/WebsiteHosting.html',
    note: 'Verified live against a real, deliberately nonexistent bucket while building this tool: a GET returns HTTP 404 with an XML body containing exactly this "NoSuchBucket" code.',
  },
  {
    id: 'heroku',
