    note: 'A deleted or renamed app leaves the DNS target dangling; Heroku will let a new app claim the same name.',
  },
  {
    id: 'github-pages',
    name: 'GitHub Pages',
    cnamePattern: /(^|\.)github\.io$/i,
    fingerprint: /There isn'?t a GitHub Pages site here/i,
