    fingerprint: /The site you were looking for could not be found/i,
    vulnerable: true,
    docsUrl: 'https://docs.pantheon.io/domains',
    note: null,
  },
  {
    id: 'bitbucket',
    name: 'Bitbucket Cloud (static site)',
    cnamePattern: /(^|\.)bitbucket\.io$/i,
    fingerprint: /Repository not found/i,
