    note: null,
  },
];

/** Finds the first provider whose `cnamePattern` matches a CNAME target
 * hostname (already normalized: trailing dot stripped, lowercased). Returns
 * `null` when the target does not match any known provider -- see
 * analyze.mjs's `no-known-provider` category for what that means. */
export function matchProvider(targetHost) {
  if (!targetHost) return null;
  const host = String(targetHost).replace(/\.$/, '').toLowerCase();
  return PROVIDERS.find((p) => p.cnamePattern.test(host)) ?? null;
}

lookup.mjs.text:
// The only file in this venture that makes a DNS call. Uses the platform's
// own global `fetch` -- zero-dependency, so this module runs unmodified from
// check.mjs on the user's own machine and from index.html's
// <script type=module> in the visitor's own browser -- the same shape
// ventures/email-auth-check/lookup.mjs documents. Either way the request
// goes straight from that machine to Cloudflare's public DNS-over-HTTPS
// resolver; no server of ours sits in between, and nothing about the
// hostname being checked is sent anywhere but Cloudflare.
//
// Cloudflare's DoH JSON API
// (https://developers.cloudflare.com/1.1.1.1/encrypted-dns/dns-over-https/make-api-requests/dns-json/)
// is public, free, needs no key, and answers CORS-enabled, so it is the one
// DNS lookup path reachable from a static page with no server of its own.

const DOH_ENDPOINT = 'https://cloudflare-dns.com/dns-query';
const DEFAULT_TIMEOUT_MS = 8000;
const DEFAULT_MAX_HOPS = 8;

/**
 * One DNS CNAME query via Cloudflare's public DoH JSON API.
 *
 * @returns {{ok: boolean, target: string|null, error: string|null}}
 *   `target` is the CNAME's target hostname with the trailing root dot
 *   stripped, or `null` when the name genuinely has no CNAME record
 *   (including NXDOMAIN) -- a real, reportable "not CNAME-based" answer.
 *   `target` is only meaningfully `null` when `ok` is true; `ok: false`
 *   means the record's true state was never learned (a transport failure)
 *   and must never be read as "no CNAME".
 */
export async function dohQueryCname(name, { fetchImpl = globalThis.fetch, timeoutMs = DEFAULT_TIMEOUT_MS } = {}) {
  if (typeof fetchImpl !== 'function') {
    return { ok: false, target: null, error: 'no fetch implementation available in this runtime' };
  }
  const url = `${DOH_ENDPOINT}?name=${encodeURIComponent(name)}&type=CNAME`;
  const controller = typeof AbortController === 'function' ? new AbortController() : null;
  const timer = controller ? setTimeout(() => controller.abort(), timeoutMs) : null;
  try {
    const res = await fetchImpl(url, {
      headers: { accept: 'application/dns-json' },
      signal: controller ? controller.signal : undefined,
    });
    if (!res.ok) {
      return { ok: false, target: null, error: `HTTP ${res.status} from the DNS resolver` };
    }
    const body = await res.json();
    // RFC 1035 RCODEs, as Cloudflare's JSON API reports them in `Status`.
    if (body.Status === 3) return { ok: true, target: null, error: null }; // NXDOMAIN: real, reportable absence
    if (body.Status !== 0) {
      return { ok: false, target: null, error: `DNS resolver returned RCODE ${body.Status}` };
    }
    const cnameAnswer = (body.Answer || []).find((a) => a && a.type === 5); // 5 = CNAME
    const target = cnameAnswer ? String(cnameAnswer.data).replace(/\.$/, '') : null;
    return { ok: true, target, error: null };
  } catch (err) {
    const timedOut = err && err.name === 'AbortError';
    return {
      ok: false,
      target: null,
      error: timedOut ? 'timed out' : String((err && err.message) || err || 'unknown error'),
    };
  } finally {
    if (timer) clearTimeout(timer);
  }
}

/**
 * Follows a hostname's CNAME chain to its end: `blog.example.com` ->
 * `old-app.herokuapp.com` -> (no further CNAME). Stops at the first name
 * with no CNAME record (real end of the chain, whether or not it then
 * resolves to an A/AAAA record -- this tool never checks those), at
 * `maxHops`, or at a repeated name (a CNAME loop, which is a DNS
 * misconfiguration of its own and never a takeover finding this tool makes).
 *
 * @returns {{chain: string[], finalTarget: string|null, truncated: boolean, error: string|null}}
 *   `chain` always starts with the hostname itself. `finalTarget` is the
 *   last CNAME target found (`null` when the root hostname itself has no
 *   CNAME at all -- see analyze.mjs's `no-cname` category).
 */
export async function resolveCnameChain(hostname, { fetchTxt = dohQueryCname, timeoutMs, maxHops = DEFAULT_MAX_HOPS } = {}) {
  const chain = [hostname];
  const seen = new Set([hostname.toLowerCase()]);
  let current = hostname;
  let finalTarget = null;
  let truncated = false;

  for (let hop = 0; hop < maxHops; hop++) {
    const result = await fetchTxt(current, { timeoutMs });
    if (!result.ok) {
      return { chain, finalTarget, truncated: false, error: result.error };
    }
    if (!result.target) break; // real end of the chain
    if (seen.has(result.target.toLowerCase())) {
      truncated = true; // a CNAME loop -- stop rather than spin forever
      break;
    }
    finalTarget = result.target;
    chain.push(result.target);
    seen.add(result.target.toLowerCase());
    current = result.target;
    if (hop === maxHops - 1) truncated = true;
  }

  return { chain, finalTarget, truncated, error: null };
}

probe.mjs.text:
// Real-network layer: sends one plain GET request to a hostname and returns
// exactly what came back -- status and a byte-capped body, nothing else.
// Deliberately the same module imported unmodified by the CLI (Node's
// built-in `fetch`) and by the browser page (`index.html` imports it
// directly), the same shape `ventures/dotenv-exposure-check/probe.mjs`
// documents.
//
// This module never inspects the body -- it only fetches; classification
// against a provider's fingerprint happens in analyze.mjs.
//
// Whether a browser run can complete depends on the target's own CORS
// policy for a plain cross-origin GET -- most third-party hosting providers
// do not send permissive CORS headers on their catch-all "not found" pages,
// so a cross-origin browser fetch commonly fails with a generic, status-less
// network error. This module never guesses which cause that was; it reports
// it as an unclassified `error`. The CLI, run from a machine rather than a
// browser tab, is not subject to CORS at all and is the one path guaranteed
// to complete.
//
// This module only ever sends a single GET request to the one hostname the
// caller named.

const DEFAULT_TIMEOUT_MS = 10_000;
const USER_AGENT =
  'subdomain-takeover-check/1 (+https://duncan-haywood.github.io/monorepo-projects/subdomain-takeover-check/)';
// A provider's "unclaimed" page is normally small. Generous enough to still
// see the fingerprint text while bounding what this tool ever holds in
// memory or could be made to download on repeat.
const MAX_BODY_BYTES = 200_000;

async function timedFetch(url, init, timeoutMs, fetchImpl) {
  const doFetch = fetchImpl ?? globalThis.fetch;
  if (typeof doFetch !== 'function') {
    throw new Error('no fetch implementation available in this environment');
  }
  const controller = new AbortController();
  const timer = setTimeout(() => controller.abort(), timeoutMs);
  try {
    return await doFetch(url, { ...init, signal: controller.signal });
  } finally {
    clearTimeout(timer);
  }
}

async function readCapped(res, maxBytes) {
  if (!res.body?.getReader) {
    const text = await res.text();
    return text.length > maxBytes ? text.slice(0, maxBytes) : text;
  }
  const reader = res.body.getReader();
  const chunks = [];
  let total = 0;
  for (;;) {
    const { done, value } = await reader.read();
    if (done) break;
    total += value.byteLength;
    chunks.push(value);
    if (total >= maxBytes) {
      try { await reader.cancel(); } catch { /* best effort */ }
      break;
    }
  }
  const combined = new Uint8Array(Math.min(total, maxBytes));
  let offset = 0;
  for (const chunk of chunks) {
    const room = combined.length - offset;
    if (room <= 0) break;
    combined.set(room < chunk.length ? chunk.subarray(0, room) : chunk, offset);
    offset += Math.min(chunk.length, room);
  }
  return new TextDecoder('utf-8', { fatal: false }).decode(combined);
}

/**
 * One GET request to `url` (a full URL, e.g. `https://blog.example.com/` or
 * a test server's loopback base). Never throws on an ordinary HTTP or
 * network failure -- those come back as `ok: false` with `error` set, since
 * a status-carrying response (even a 404 or 500) is still evidence a caller
 * may want, distinct from "the request never completed at all".
 */
export async function fetchHost(url, { timeoutMs = DEFAULT_TIMEOUT_MS, fetchImpl } = {}) {
  let res;
  try {
    res = await timedFetch(
      url,
      { method: 'GET', headers: { 'user-agent': USER_AGENT, accept: 'text/html,*/*' } },
      timeoutMs,
      fetchImpl,
    );
  } catch (err) {
    return { url, ok: false, status: null, text: null, error: err.message ?? String(err) };
  }
  let text;
  try {
    text = await readCapped(res, MAX_BODY_BYTES);
  } catch (err) {
    return { url, ok: false, status: res.status, text: null, error: err.message ?? String(err) };
  }
  // A provider's own fingerprint page is often served with a 404 status --
  // that is expected (it is, after all, "not found"), so `ok` here tracks
  // "did we get a body to check", not HTTP-success. A response with no body
  // at all is not useful evidence either way.
  return { url, ok: true, status: res.status, text, error: null };
}

/** Convenience wrapper: builds `https://<hostname>/` and fetches it. Tests
 * that need a loopback base URL call `fetchHost` directly instead. */
export async function fetchHostname(hostname, opts = {}) {
  return fetchHost(`https://${hostname}/`, opts);
}

usage.mjs.text:
// Records an anonymous, aggregate-only local usage count: the event name and
// the current day, kept in the visitor's own browser. It never stores the
// hostname checked or anything about what was found -- that is exactly the
// kind of thing that must not be transmitted anywhere, and this tool never
// reads it off the visitor's machine either.

const STORAGE_KEY = 'subdomain-takeover-check-usage';

function honorsBrowserSignal() {
  try {
    return globalThis.navigator?.doNotTrack === '1' || globalThis.navigator?.globalPrivacyControl === true;
  } catch {
    return false;
  }
}

export function recordUsage(storage = globalThis.localStorage, optedOut = false, event = 'check_run') {
  if (optedOut || !storage || readOptOut(storage) || honorsBrowserSignal()) return;
  try {
    const today = new Date().toISOString().slice(0, 10);
    const current = JSON.parse(storage.getItem(STORAGE_KEY) || '{}');
    current[event] = (current[event] || 0) + 1;
    current.last_day = today;
    storage.setItem(STORAGE_KEY, JSON.stringify(current));
  } catch {
    // A browser refusing site data must not stop the page computing a result.
  }
}

// The opt-out choice is kept in its own key, not in the counters:
// opting out *removes* the counters, so a flag stored inside them would
// be deleted by the very act it records. `recordUsage` above consults it
// directly as well as taking the caller's argument -- a stored preference
// that only one line of page wiring reads is one line away from being
// forgotten.
export function readOptOut(storage = globalThis.localStorage) {
  try {
    return storage?.getItem(`${STORAGE_KEY}-opt-out`) === '1';
  } catch {
    // A blocked or full store must never be read as consent.
    return false;
  }
}

export function writeOptOut(storage = globalThis.localStorage, optedOut = false) {
  if (!storage) return;
  // Independent writes, counters first: sharing one try means a setItem
  // that throws on a full quota skips the delete entirely, and the
  // visitor gets neither half of what the control promised.
  if (optedOut) {
    try { storage.removeItem(STORAGE_KEY); } catch { /* storage is optional */ }
    try { storage.setItem(`${STORAGE_KEY}-opt-out`, '1'); } catch { /* storage is optional */ }
  } else {
    try { storage.removeItem(`${STORAGE_KEY}-opt-out`); } catch { /* storage is optional */ }
  }
}
